WITH filtered AS (SELECT id, customer_id, device, started_at, country, CONCAT(device, ' ', browser) AS device_browser, COALESCE(country, 'DIRECT') AS country_clean FROM sessions WHERE started_at > TO_DATE('2023-11-16')), kept AS (SELECT s.* FROM filtered s WHERE EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.page IN ('/search', '/checkout', '/home'))), gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM kept), sessions_sessions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT burst_id, SUM(is_new_session) FILTER (WHERE device = 'tablet') AS tablet_total_is_new_session, SUM(CASE WHEN device = 'desktop' THEN burst_id ELSE 0 END) AS desktop_burst_id FROM sessions_sessions GROUP BY burst_id ORDER BY burst_id DESC NULLS LAST
